const defaults: Settings = { sourceRoot: "", outputRoot: "", stylePrompt: "", paletteColors: defaultPalette, loraEnabled: false, loraStrength: 1, fluxDenoisingStrength: 0.72, structurePreservation: 0.6, inferenceSteps: 8, overwrite: false, view: "grid", groupBy: "none", styleLockEnabled: true, styleSeed: 24681357, workingResolution: 1024, minimumResolutionEnabled: true, contentAwareScaling: true, leftPanelWidth: 240, rightPanelWidth: 380 };
