  systemScanActive = true; downloadHardwareApproved = false; $("#preflight-modal").hidden = false;
  $("#preflight-body").innerHTML = '<div class="preflight-scanning"><i></i><strong>Checking this PC…</strong><span>GPU, NVIDIA driver, memory, processor, and storage</span></div>';
