  $("#open-resources").classList.toggle("needs-download", missing > 0 || statusUnavailable); $("#resources-installed").textContent = runtimeResources.length ? `${installed} of ${required.length} required installed` : "Resource status unavailable"; $("#resources-summary-text").textContent = runtimeResources.length ? missing ? `${missing} required component${missing === 1 ? " is" : "s are"} missing` : "All required model components are ready" : "Refresh to check the local installation";
  if (!runtimeResources.length) { $("#resources-list").innerHTML = "<p>No resource inventory was returned.</p>"; return; }
