  const groups = [...new Set(runtimeResources.map(resource => resource.group))].sort((a, b) => (groupOrder.indexOf(a) < 0 ? 99 : groupOrder.indexOf(a)) - (groupOrder.indexOf(b) < 0 ? 99 : groupOrder.indexOf(b)));
